/* M.V.P. Accelerator, Player-Coach track: narration text and timing cues (round 3, Dennis). Generated by _generators/cues_r3.py. */
window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_1_3": {"dur": 13.12, "text": "Now take one clean read of how you react, before you learn the rest of the system. This drill is short. Press Play. Melissa will pause partway through and ask what you notice. Type your answer, and the video will resume.", "sents": [[0.03, "Now take one clean read of how you react, before you learn the rest of the system.", 0], [4.87, "This drill is short.", 0], [6.15, "Press Play.", 1], [7.21, "Melissa will pause partway through and ask what you notice.", 1], [10.69, "Type your answer, and the video will resume.", 1]], "v": "k1", "cues": [0.03, 6.15]}, "n_1_8_agility": {"dur": 12.24, "text": "When agility is conditioned, you don't need certainty to move. You make the call and adjust as things change. When it isn't, you wait for certainty while everything keeps changing around you.", "sents": [[0.01, "When agility is conditioned, you don't need certainty to move.", 0], [4.43, "You make the call and adjust as things change.", 0], [7.55, "When it isn't, you wait for certainty while everything keeps changing around you.", 1]], "v": "v4l", "cues": [0.01, 7.55]}, "n_1_8_alignment": {"dur": 12.08, "text": "When alignment is conditioned, you know what matters most. You make the hard call and keep people moving in the same direction. When it isn't, everything feels urgent and people pull in different directions.", "sents": [[0.01, "When alignment is conditioned, you know what matters most.", 0], [3.93, "You make the hard call and keep people moving in the same direction.", 0], [7.71, "When it isn't, everything feels urgent and people pull in different directions.", 1]], "v": "k1", "cues": [0.01, 7.71]}, "n_1_8_resilience": {"dur": 10.24, "text": "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play. When it isn't, one hard moment follows you into the next one.", "sents": [[0.07, "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play.", 0], [6.47, "When it isn't, one hard moment follows you into the next one.", 1]], "v": "r3", "cues": [0.07, 6.47]}, "n_1_8_wellbeing": {"dur": 12.08, "text": "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises. When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", "sents": [[0.01, "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises.", 0], [7.77, "When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", 1]], "v": "v4l", "cues": [0.01, 7.77]}, "n_1_R": {"dur": 54.0, "text": "Before your first Moment, here's one tool you'll use all season. It's called the Foundation Reset, and it comes from Melissa's book. Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex. Your five words tell the alarm to stand down and bring your thinking brain back online. Melissa used it in a hotel hallway, less than two days before her biggest summit, as the world shut down for the COVID-19 pandemic. Five words: “I'm not in danger, deciding.” Two options: cancel or pivot? One default: “We pivot, now.” Thirty-eight hours later, her summit went live as one of the first global virtual leadership events. Now write your own five words. Use one of Melissa's to start, or write words that would steady you. Select Save, and you'll see them again in every check-in.", "sents": [[0, "Before your first Moment, here's one tool you'll use all season.", 0], [4.45, "It's called the Foundation Reset, and it comes from Melissa's book.", 0], [8.49, "Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex.", 1], [15.83, "Your five words tell the alarm to stand down and bring your thinking brain back online.", 1], [21.27, "Melissa used it in a hotel hallway, less than two days before her biggest summit, as the world shut down for the COVID-19 pandemic.", 2], [30.65, "Five words: “I'm not in danger, deciding.”", 2], [33.19, "Two options: cancel or pivot?", 2], [34.99, "One default: “We pivot, now.”", 2], [37.37, "Thirty-eight hours later, her summit went live as one of the first global virtual leadership events.", 2], [45.21, "Now write your own five words.", 3], [47.17, "Use one of Melissa's to start, or write words that would steady you.", 3], [50.87, "Select Save, and you'll see them again in every check-in.", 3]], "v": "p1", "cues": [0, 8.49, 21.27, 45.21]}, "pc_n_1_0": {"dur": 11.2, "text": "Lesson 1 is about the role you're stepping into. You'll spend about 35 minutes here. Your core rep this week is one 30-minute conversation with your Athleader. Select Start Lesson.", "sents": [[0, "Lesson 1 is about the role you're stepping into.", 0], [3.11, "You'll spend about 35 minutes here.", 1], [5.41, "Your core rep this week is one 30-minute conversation with your Athleader.", 1], [9.79, "Select Start Lesson.", 1]], "v": "r3L", "cues": [0, 3.11]}, "pc_n_1_1": {"dur": 13.2, "text": "Read this moment and picture yourself in it. Most managers say something like this and mean it kindly. This season asks more of you, and the first thing it asks for is one conversation in the next week.", "sents": [[0, "Read this moment and picture yourself in it.", 0], [3.43, "Most managers say something like this and mean it kindly.", 1], [7.17, "This season asks more of you, and the first thing it asks for is one conversation in the next week.", 1]], "v": "r3", "cues": [0, 3.43]}, "pc_n_1_10": {"dur": 16.0, "text": "Agility, Resilience, Alignment, and Wellbeing are the same four your Athleader is conditioning, so you'll share a language all season. Select each one to hear what changes when it's conditioned. As you listen, think about which one your team would say you're weakest on.", "sents": [[0.05, "Agility, Resilience, Alignment, and Wellbeing are the same four your Athleader is conditioning, so you'll share a language all season.", 0], [8.87, "Select each one to hear what changes when it's conditioned.", 1], [12.09, "As you listen, think about which one your team would say you're weakest on.", 1]], "v": "r3", "cues": [0.05, 8.87]}, "pc_n_1_12": {"dur": 28.48, "text": "Melissa's example shows the multiplier at work. David managed Kim, and her presentation skills were holding her back. So he spent time coaching her before a big client pitch. Kim led the pitch, and the team won the contract. Morale went up, and senior leaders noticed the whole team. That's the Manager Multiplier Effect: Coach one person well, and the gain spreads through the team. In your Playbook this week, you'll name where that could happen with your Athleader.", "sents": [[0, "Melissa's example shows the multiplier at work.", 0], [3.51, "David managed Kim, and her presentation skills were holding her back.", 1], [7.71, "So he spent time coaching her before a big client pitch.", 2], [11.29, "Kim led the pitch, and the team won the contract.", 3], [14.33, "Morale went up, and senior leaders noticed the whole team.", 3], [18.01, "That's the Manager Multiplier Effect: Coach one person well, and the gain spreads through the team.", 4], [22.83, "In your Playbook this week, you'll name where that could happen with your Athleader.", 4]], "v": "r3", "cues": [0, 3.51, 7.71, 11.29, 18.01]}, "pc_n_1_14": {"dur": 34.24, "text": "This is the agenda for the meeting Melissa just described. On her agenda, it's called the Starting Line, and it takes thirty minutes. Start by arriving. Take five minutes to put the week down so you're both actually in the room. Then name the win. Ask what will have changed ninety days from now, and answer it for yourself too. Next, get honest about what each of you tends to drop when things get busy and say what you need from each other. Before you leave, book a recurring fifteen-minute check-in for the season. Open the agenda to see the full version, including the commitment you both sign.", "sents": [[0, "This is the agenda for the meeting Melissa just described.", 0], [3.19, "On her agenda, it's called the Starting Line, and it takes thirty minutes.", 0], [7.67, "Start by arriving.", 1], [9.21, "Take five minutes to put the week down so you're both actually in the room.", 1], [12.99, "Then name the win.", 2], [14.87, "Ask what will have changed ninety days from now, and answer it for yourself too.", 2], [19.41, "Next, get honest about what each of you tends to drop when things get busy and say what you need from each other.", 3], [25.97, "Before you leave, book a recurring fifteen-minute check-in for the season.", 4], [30.09, "Open the agenda to see the full version, including the commitment you both sign.", 4]], "v": "pc1", "cues": [0, 7.67, 12.99, 19.41, 25.97]}, "pc_n_1_15": {"dur": 9.68, "text": "Let's put the Starting Line under a little pressure. Your Athleader is hesitant, and their answers stay general. Pick the move you'd make, and you'll hear where it leads.", "sents": [[0, "Let's put the Starting Line under a little pressure.", 0], [3.15, "Your Athleader is hesitant, and their answers stay general.", 1], [6.83, "Pick the move you'd make, and you'll hear where it leads.", 1]], "v": "r3L", "cues": [0, 3.15]}, "pc_n_1_15_o0": {"dur": 13.6, "text": "Offering your own ideas feels helpful, and it fills an awkward silence. The trouble is that they leave with your goals rather than theirs, and they learn it's safer to wait for you next time. Try the other option to compare.", "sents": [[0.03, "Offering your own ideas feels helpful, and it fills an awkward silence.", 0], [5.11, "The trouble is that they leave with your goals rather than theirs, and they learn it's safer to wait for you next time.", 0], [11.87, "Try the other option to compare.", 0]], "v": "r3L", "cues": [0.03]}, "pc_n_1_15_o1": {"dur": 11.36, "text": "That question is about them, and it has no wrong answer. Then you wait. The pause after it is usually where the real goal shows up, and you've shown them it's safe to say it.", "sents": [[0.05, "That question is about them, and it has no wrong answer.", 0], [4.11, "Then you wait.", 0], [4.69, "The pause after it is usually where the real goal shows up, and you've shown them it's safe to say it.", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_1_16": {"dur": 27.76, "text": "Your core rep this week is the Starting Line, a thirty-minute conversation with your Athleader. Book it and hold it, using the agenda. If you have more time, start with your intention. Name the pressure point you feel now and the wellbeing practice you'll start. Write down where your Athleader's growth would lift the team. Be specific about the outcome. Complete your core rep, then ask your Athleader for feedback. Select Open your Lesson 1 pages to get started.", "sents": [[0.01, "Your core rep this week is the Starting Line, a thirty-minute conversation with your Athleader.", 0], [5.67, "Book it and hold it, using the agenda.", 0], [8.55, "If you have more time, start with your intention.", 1], [11.51, "Name the pressure point you feel now and the wellbeing practice you'll start.", 1], [15.83, "Write down where your Athleader's growth would lift the team.", 2], [19.09, "Be specific about the outcome.", 2], [21.33, "Complete your core rep, then ask your Athleader for feedback.", 3], [24.91, "Select Open your Lesson 1 pages to get started.", 3]], "v": "pc1", "cues": [0.01, 8.55, 15.83, 21.33]}, "pc_n_1_17": {"dur": 10.4, "text": "Each lesson brings in an Athleader Pro, a leader who lives one part of this work. This time you'll hear from Tracey Newell, the Change Commander. Press Play to hear from her.", "sents": [[0, "Each lesson brings in an Athleader Pro, a leader who lives one part of this work.", 0], [5.37, "This time you'll hear from Tracey Newell, the Change Commander.", 1], [8.99, "Press Play to hear from her.", 1]], "v": "pc1", "cues": [0, 5.37]}, "pc_n_1_18": {"dur": 12.0, "text": "Now try Tracey's drill. It takes three minutes. Select Start the timer and work through each step as it lights up. When you've completed the drill or scheduled a time to run it, select the option that fits.", "sents": [[0.07, "Now try Tracey's drill.", 0], [1.79, "It takes three minutes.", 0], [3.33, "Select Start the timer and work through each step as it lights up.", 1], [7.37, "When you've completed the drill or scheduled a time to run it, select the option that fits.", 1]], "v": "pc1", "cues": [0.07, 3.33]}, "pc_n_1_20_q0": {"dur": 8.72, "text": "A few questions to check the main ideas. First: what does the Manager Multiplier Effect describe? Choose one, then select Submit.", "sents": [[0, "A few questions to check the main ideas.", 0], [2.47, "First: what does the Manager Multiplier Effect describe?", 0], [6.53, "Choose one, then select Submit.", 0]], "v": "r3L", "cues": [0]}, "pc_n_1_20_q1": {"dur": 3.2, "text": "Why does leading yourself come before leading others?", "sents": [[0.05, "Why does leading yourself come before leading others?", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_1_20_q2": {"dur": 6.48, "text": "In the Starting Line, your Athleader says, I'm not sure what I want from this yet. What's the best next move?", "sents": [[0, "In the Starting Line, your Athleader says, I'm not sure what I want from this yet.", 0], [5.03, "What's the best next move?", 0]], "v": "r3L", "cues": [0]}, "pc_n_1_20_q3": {"dur": 3.68, "text": "Last one. What should every Starting Line end with?", "sents": [[0, "Last one.", 0], [1.17, "What should every Starting Line end with?", 0]], "v": "r3", "cues": [0]}, "pc_n_1_20_w0": {"dur": 8.08, "text": "When you coach one person well, their better work and engagement carry across the team, the way Kim's pitch won the contract for everyone.", "sents": [[0.07, "When you coach one person well, their better work and engagement carry across the team, the way Kim's pitch won the contract for everyone.", 0]], "v": "r3L", "cues": [0.07]}, "pc_n_1_20_w1": {"dur": 9.92, "text": "Melissa's own story makes the point. When she was running on empty, her team felt it. Looking after your own energy is what lets you be the anchor.", "sents": [[0.01, "Melissa's own story makes the point.", 0], [2.59, "When she was running on empty, her team felt it.", 0], [6.17, "Looking after your own energy is what lets you be the anchor.", 0]], "v": "r3L", "cues": [0.01]}, "pc_n_1_20_w2": {"dur": 9.92, "text": "An open question with no wrong answer, followed by a real pause makes it safe for them to find their own goal. Suggesting goals hands them yours.", "sents": [[0.01, "An open question with no wrong answer, followed by a real pause makes it safe for them to find their own goal.", 0], [7.47, "Suggesting goals hands them yours.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_1_20_w3": {"dur": 8.64, "text": "The rhythm is what carries the season. Book the fifteen-minute check-in before you leave the room, and the rest of the lessons have somewhere to land.", "sents": [[0.03, "The rhythm is what carries the season.", 0], [3.09, "Book the fifteen-minute check-in before you leave the room, and the rest of the lessons have somewhere to land.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_1_21": {"dur": 34.08, "text": "Before you go, here's what to keep from this lesson. You have two roles this season. You're conditioning your own leadership and coaching your Athleader through theirs. Looking after yourself comes first. When you coach one person well, the whole team gains. Your Playbook asks you to name where that could happen. And the Starting Line sets the rhythm for everything after it. Book it this week. Select Download my answers for a Word document containing what you wrote in this lesson. If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.37, "You have two roles this season.", 1], [5.53, "You're conditioning your own leadership and coaching your Athleader through theirs.", 1], [9.91, "Looking after yourself comes first.", 1], [12.57, "When you coach one person well, the whole team gains.", 2], [15.89, "Your Playbook asks you to name where that could happen.", 2], [18.89, "And the Starting Line sets the rhythm for everything after it.", 3], [22.51, "Book it this week.", 3], [23.75, "Select Download my answers for a Word document containing what you wrote in this lesson.", 4], [28.55, "If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", 4]], "v": "pc1", "cues": [0.03, 3.37, 12.57, 18.89, 23.75]}, "pc_n_1_22": {"dur": 18.64, "text": "That's Lesson 1 done. Way to go! You've stepped into the Player-Coach role. This week, complete your core rep: book and hold the Starting Line with your Athleader, then ask how it landed. Next time, you'll draft your own M.V.P.+V because it's hard to coach someone through work you haven't done yourself.", "sents": [[0.01, "That's Lesson 1 done.", 0], [1.73, "Way to go!", 0], [3.01, "You've stepped into the Player-Coach role.", 0], [5.53, "This week, complete your core rep: book and hold the Starting Line with your Athleader, then ask how it landed.", 1], [11.87, "Next time, you'll draft your own M.V.P.+V because it's hard to coach someone through work you haven't done yourself.", 1]], "v": "pc1", "cues": [0.01, 5.53]}, "pc_n_1_4": {"dur": 28.24, "text": "Here's what you'll practice in this lesson. You're doing two things this season: You're working on your own leadership, and you're coaching your Athleader while they work on theirs. You'll name one pressure point you feel right now and one wellbeing practice you'll start this week to handle it. You'll pick one place where your Athleader's growth would lift the whole team. Melissa calls this the Manager Multiplier Effect. And you'll hold your first conversation with your Athleader, the Starting Line. That's your core rep this week.", "sents": [[0.03, "Here's what you'll practice in this lesson.", 0], [2.25, "You're doing two things this season: You're working on your own leadership, and you're coaching your Athleader while they work on theirs.", 1], [9.39, "You'll name one pressure point you feel right now and one wellbeing practice you'll start this week to handle it.", 2], [15.31, "You'll pick one place where your Athleader's growth would lift the whole team.", 3], [19.39, "Melissa calls this the Manager Multiplier Effect.", 3], [22.45, "And you'll hold your first conversation with your Athleader, the Starting Line.", 4], [26.69, "That's your core rep this week.", 4]], "v": "r3", "cues": [0.03, 2.25, 9.39, 15.31, 22.45]}, "pc_n_1_6": {"dur": 15.36, "text": "Melissa just asked you to name one leadership behavior you want to strengthen. Write it here in one sentence. Make it something your team would notice if it changed. It's saved, and you'll see it again in Lesson 6. Then select Next to download your Playbook.", "sents": [[0, "Melissa just asked you to name one leadership behavior you want to strengthen.", 0], [4.43, "Write it here in one sentence.", 1], [6.77, "Make it something your team would notice if it changed.", 1], [9.67, "It's saved, and you'll see it again in Lesson 6.", 1], [12.73, "Then select Next to download your Playbook.", 2]], "v": "r3L", "cues": [0, 4.43, 12.73]}, "pc_n_1_7": {"dur": 10.56, "text": "Now download your Player-Coach Playbook because every lesson uses it. It opens in a new tab. Save a copy somewhere you'll find it. If you already saved it during setup, you're all set.", "sents": [[0, "Now download your Player-Coach Playbook because every lesson uses it.", 0], [4.23, "It opens in a new tab.", 1], [5.79, "Save a copy somewhere you'll find it.", 1], [7.83, "If you already saved it during setup, you're all set.", 1]], "v": "pc1", "cues": [0, 4.23]}, "pc_n_1_9": {"dur": 30.88, "text": "Here's the shape of Melissa's story. She was running a business and caring for her family, and she was worn out. Her team felt it, and so did her family. She described it as surviving rather than leading. What changed things was treating her own wellbeing as fixed on the calendar, with recovery time that she protected. Once she did that, she could lead her team through change again. So this week, put one recovery block on your calendar and keep it. Your team takes its steadiness from you.", "sents": [[0.05, "Here's the shape of Melissa's story.", 0], [2.39, "She was running a business and caring for her family, and she was worn out.", 1], [7.07, "Her team felt it, and so did her family.", 1], [10.19, "She described it as surviving rather than leading.", 1], [13.71, "What changed things was treating her own wellbeing as fixed on the calendar, with recovery time that she protected.", 2], [20.41, "Once she did that, she could lead her team through change again.", 3], [24.17, "So this week, put one recovery block on your calendar and keep it.", 4], [28.43, "Your team takes its steadiness from you.", 4]], "v": "pc1", "cues": [0.05, 2.39, 13.71, 20.41, 24.17]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
